#include "m1_local_fast2d/candidate_risk_scorer.hpp"
#include <algorithm>
#include <cmath>
namespace m1_local_fast2d { namespace { constexpr int64_t NS=1000000000LL; bool sample(const m1_local_fast2d::msg::TimedTrajectory&t,double q,double&x,double&y){if(t.points.empty()||q<0||q>t.points.back().time_from_start)return false;for(size_t i=1;i<t.points.size();++i)if(q<=t.points[i].time_from_start){auto&a=t.points[i-1];auto&b=t.points[i];double d=b.time_from_start-a.time_from_start;if(d<=0)return false;double u=(q-a.time_from_start)/d;x=a.x+u*(b.x-a.x);y=a.y+u*(b.y-a.y);return true;}x=t.points.back().x;y=t.points.back().y;return true;}}
m1_local_fast2d::msg::CandidateRiskScore CandidateRiskScorer::score(const m1_local_fast2d::msg::TimedTrajectory&t,uint32_t idx,const m1_scope_risk::RiskFieldSnapshot&s,int64_t stamp,int64_t now,const CandidateRiskScoringConfig&c){m1_local_fast2d::msg::CandidateRiskScore o;o.planning_result_id=t.planning_result_id;o.candidate_index=idx;o.scope_prediction_id=s.predictionId();if(t.points.empty()||c.dt<=0||!s.isFresh(now))return o;double dur=t.points.back().time_from_start;if(dur<=0)return o;o.trajectory_duration=dur;double sum=0,cov=0;for(double q=c.dt;q<=dur+1e-9;q+=c.dt){double x,y;if(!sample(t,std::min(q,dur),x,y)){++o.missing_query_count;continue;}auto r=s.query(x,y,(stamp+static_cast<int64_t>(std::llround(q*NS))-s.anchorStampNs())/1e9,now);double w=std::min(c.dt,dur-(q-c.dt));if(!r){++o.missing_query_count;continue;}++o.valid_query_count;cov+=w;sum+=*r*w;o.max_risk=std::max(o.max_risk,*r);if(*r>=c.high_threshold){++o.high_risk_fraction;if(!o.has_high_risk){o.has_high_risk=true;auto n=static_cast<int64_t>(std::llround(q*NS));o.first_high_risk_time.sec=n/NS;o.first_high_risk_time.nanosec=n%NS;}}}if(!o.valid_query_count)return o;o.prediction_covered_duration=cov;o.coverage_ratio=std::min(1.0,cov/dur);o.integrated_risk=sum;o.mean_risk=sum/cov;o.high_risk_fraction/=o.valid_query_count;o.score_valid=true;o.coverage_sufficient=o.coverage_ratio>=c.minimum_coverage_ratio;return o;}}
